WITH recent_ship_sales AS ( SELECT cc.cc_name AS call_center_name, cs.cs_ship_mode_sk AS ship_mode, cs.cs_net_profit, cs.cs_net_paid_inc_tax, d.d_year FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN date_dim d ON cs.cs_ship_date_sk = d.d_date_sk WHERE d.d_year = (SELECT MAX(d_year) FROM date_dim) ) SELECT call_center_name, ship_mode, SUM(cs_net_profit) AS total_profit, SUM(cs_net_paid_inc_tax) AS total_paid, SUM(cs_net_profit) / NULLIF(SUM(cs_net_paid_inc_tax),0) AS profit_margin, PERCENT_RANK() OVER (PARTITION BY call_center_name ORDER BY SUM(cs_net_profit) / NULLIF(SUM(cs_net_paid_inc_tax),0) DESC) AS profit_percentile FROM recent_ship_sales GROUP BY call_center_name, ship_mode ORDER BY profit_percentile ASC
